if(!defined('ABSPATH')){exit;}final class QualityRoutes{private const TYPES=array('bugs'=>'bug','test-cases'=>'test-case');public static function register_routes():void{register_rest_route(Routes::NAMESPACE,'/projects/(?P<project>[A-Za-z0-9_-]+)/quality/(?P<type>bugs|test-cases)',array(array('methods'=>WP_REST_Server::READABLE,'callback'=>array(self::class,'index'),'permission_callback'=>array(self::class,'can_read')),array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array(self::class,'create'),'permission_callback'=>array(self::class,'can_edit'))));register_rest_route(Routes::NAMESPACE,'/projects/(?P<project>[A-Za-z0-9_-]+)/quality/(?P<type>bugs|test-cases)/(?P<id>\d+)',array(array('methods'=>WP_REST_Server::EDITABLE,'callback'=>array(self::class,'update'),'permission_callback'=>array(self::class,'can_edit')),array('methods'=>WP_REST_Server::DELETABLE,'callback'=>array(self::class,'delete'),'permission_callback'=>array(self::class,'can_edit'))));}public static function index(WP_REST_Request$r){$project=self::project($r);if(is_wp_error($project))return$project;$repo=self::repo($r);return self::success(array_map(static fn($item)=>$item->to_array(),$repo->for_project($project->get_id())));}public static function create(WP_REST_Request$r){$project=self::project($r);if(is_wp_error($project))return$project;$repo=self::repo($r);return self::domain(self::service($r,$repo)->create($project->get_id(),self::input($r)),201);}public static function update(WP_REST_Request$r){$project=self::project($r);if(is_wp_error($project))return$project;$repo=self::repo($r);$record=$repo->find(absint($r['id']));if(!$record||$record->get_project_id()!==$project->get_id())return self::not_found();return self::domain(self::service($r,$repo)->update($record,self::input($r)));}public static function delete(WP_REST_Request$r){$project=self::project($r);if(is_wp_error($project))return$project;$repo=self::repo($r);$record=$repo->find(absint($r['id']));if(!$record||$record->get_project_id()!==$project->get_id())return self::not_found();$result=self::service($r,$repo)->delete($record);return is_wp_error($result)?$result:self::success(array('deleted'=>(bool)$result,'id'=>$record->get_id()));}public static function can_read(WP_REST_Request$r){$p=self::project($r);return is_wp_error($p)?$p:((new ProjectPermissions())->can_view($p)?true:self::forbidden());}public static function can_edit(WP_REST_Request$r){$p=self::project($r);return is_wp_error($p)?$p:((new ProjectPermissions())->can_edit($p)?true:self::forbidden());}private static function project(WP_REST_Request$r){$p=ProjectManager::get_instance()->resolve(sanitize_text_field((string)$r->get_param('project')));return is_wp_error($p)?new WP_Error('projectpress_rest_project_not_found',__('Project not found.','projectpress'),array('status'=>404)):$p;}private static function repo(WP_REST_Request$r):QualityRepository{return new QualityRepository(self::type($r));}private static function service(WP_REST_Request$r,QualityRepository$repo):QualityService{return new QualityService(self::type($r),$repo,ProjectManager::get_instance()->repository(),new ProjectPermissions());}private static function type(WP_REST_Request$r):string{return self::TYPES[sanitize_key((string)$r['type'])]??'bug';}private static function input(WP_REST_Request$r):array{return array('title'=>sanitize_text_field((string)$r->get_param('title')),'description'=>sanitize_textarea_field((string)$r->get_param('description')),'status'=>sanitize_key((string)$r->get_param('status')),'severity'=>sanitize_key((string)$r->get_param('severity')),'target_type'=>sanitize_key((string)$r->get_param('target_type')),'target_id'=>absint($r->get_param('target_id')));}private static function success($data,int$status=200):WP_REST_Response{return new WP_REST_Response(array('success'=>true,'data'=>$data),$status);}private static function domain($x,int$status=200){return is_wp_error($x)?$x:self::success(is_object($x)&&method_exists($x,'to_array')?$x->to_array():$x,$status);}